solutionCode:
export function validarSenha(senha) {
  // 1. precisa ter pelo menos 8 caracteres
  if (senha.length < 8) return false;
  // 2. precisa conter pelo menos um número (0 a 9)
  if (!/\d/.test(senha)) return false;
  return true;
}
